 *   - Local path present and is a git repo  → git fetch + git reset --hard origin/<base>
 *
 * Exit codes:
 *   0  success
 *   2  agent.yaml validation failed
 *   3  git clone / pull failed
 *   4  unexpected bootstrap error
 */
import { execSync } from "node:child_process";
import { existsSync, readdirSync, mkdirSync, rmSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import { loadAgentYaml } from "../config/validate-agent-yaml.js";
import { parseTasksMd } from "../eligibility/parse-tasks-md.js";
import { buildGitEnv } from "../git-env.js";
// ── Exit codes ────────────────────────────────────────────────────────────────
--
 * - Already a valid git repo  → fetch + reset --hard to origin/<baseBranch>.
 * - Corrupt .git / missing refs (partial clone)  → wipe and re-clone.
 * - Directory absent, empty, or non-git  → wipe and re-clone.
 * Returns "cloned" | "pulled".
 */
export function syncRepo(url, localPath, baseBranch, gitEnv) {
    if (isGitRepo(localPath)) {
        try {
            execSync(`git -C "${localPath}" fetch origin`, { env: gitEnv, stdio: "pipe" });
            execSync(`git -C "${localPath}" reset --hard "origin/${baseBranch}"`, { env: gitEnv, stdio: "pipe" });
            return "pulled";
        }
        catch {
            // Corrupt .git (e.g. partial clone with missing refs) — wipe and re-clone.
        }
    }
    clearDir(localPath);
    execSync(`git clone "${url}" "${localPath}"`, { env: gitEnv, stdio: "pipe" });
    return "cloned";
}
