import { describe, it, expect } from "vitest";
import { extractRagQueries } from "./rag-audit.js";

function assistantToolUse(id: string, query: string) {
  return JSON.stringify({
    type: "assistant",
    message: {
      content: [
        { type: "tool_use", id, name: "mcp__rag-server__rag_query", input: { query } },
      ],
    },
  });
}

function userToolResult(toolUseId: string, scores: number[]) {
  const content = JSON.stringify(scores.map((score) => ({ score, text: "chunk" })));
  return JSON.stringify({
    type: "user",
    message: {
      content: [{ type: "tool_result", tool_use_id: toolUseId, content }],
    },
  });
}

describe("extractRagQueries", () => {
  it("returns empty array for empty stdout", () => {
    expect(extractRagQueries("")).toEqual([]);
  });

  it("extracts single RAG query with scores", () => {
    const stdout = [
      assistantToolUse("tu_1", "what is typescript"),
      userToolResult("tu_1", [0.95, 0.87, 0.72]),
    ].join("\n");
    const results = extractRagQueries(stdout);
    expect(results).toHaveLength(1);
    expect(results[0]?.query).toBe("what is typescript");
    expect(results[0]?.chunks_returned).toBe(3);
    expect(results[0]?.top_score).toBeCloseTo(0.95, 5);
    expect(results[0]?.scores).toEqual([0.95, 0.87, 0.72]);
  });

  it("extracts multiple RAG queries", () => {
    const stdout = [
      assistantToolUse("tu_1", "first query"),
      userToolResult("tu_1", [0.9]),
      assistantToolUse("tu_2", "second query"),
      userToolResult("tu_2", [0.8, 0.7]),
    ].join("\n");
    const results = extractRagQueries(stdout);
    expect(results).toHaveLength(2);
    expect(results[0]?.query).toBe("first query");
    expect(results[1]?.query).toBe("second query");
  });

  it("drops unmatched tool_use (no result)", () => {
    expect(extractRagQueries(assistantToolUse("tu_orphan", "orphan"))).toHaveLength(0);
  });

  it("sets top_score to null and chunks_returned to 0 for empty result", () => {
    const stdout = [
      assistantToolUse("tu_empty", "empty"),
      userToolResult("tu_empty", []),
    ].join("\n");
    const results = extractRagQueries(stdout);
    expect(results[0]?.chunks_returned).toBe(0);
    expect(results[0]?.top_score).toBeNull();
  });

  it("ignores non-RAG tool_use", () => {
    const stdout = [
      JSON.stringify({ type: "assistant", message: { content: [{ type: "tool_use", id: "tu_x", name: "other_tool", input: {} }] } }),
      JSON.stringify({ type: "user", message: { content: [{ type: "tool_result", tool_use_id: "tu_x", content: "[]" }] } }),
    ].join("\n");
    expect(extractRagQueries(stdout)).toHaveLength(0);
  });

  it("handles text-block content format", () => {
    const stdout = [
      assistantToolUse("tu_str", "text block query"),
      JSON.stringify({
        type: "user",
        message: {
          content: [{
            type: "tool_result",
            tool_use_id: "tu_str",
            content: [{ type: "text", text: JSON.stringify([{ score: 0.88 }, { score: 0.76 }]) }],
          }],
        },
      }),
    ].join("\n");
    const results = extractRagQueries(stdout);
    expect(results[0]?.scores).toEqual([0.88, 0.76]);
    expect(results[0]?.top_score).toBeCloseTo(0.88, 5);
  });
});

