/**
 * Token usage extraction from claude --output-format stream-json stdout.
 *
 * Extracted from the former run-claude.ts so it can be unit-tested
 * independently and reused by the executor entrypoint.
 */

/**
 * Scan stdout lines for token usage across all formats:
 *
 * - stream-json assistant events:
 *     {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,...}}}
 *   These fire once per turn; we sum all turns for the total.
 *
 * - Legacy flat usage object (plain-text / json format):
 *     {"usage":{"input_tokens":N,"output_tokens":N}}
 *
 * Returns accumulated {input, output} tokens, or undefined if no usage lines
 * are found in stdout.
 */
export function extractTokenUsage(
  stdout: string,
): { input: number; output: number } | undefined {
  let input = 0;
  let output = 0;
  let found = false;

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;

      // stream-json: assistant event carries per-turn usage inside message.
      if (parsed.type === "assistant") {
        const msg = parsed.message as Record<string, unknown> | undefined;
        const usage = msg?.usage as Record<string, unknown> | undefined;
        if (
          typeof usage?.input_tokens === "number" &&
          typeof usage?.output_tokens === "number"
        ) {
          input += usage.input_tokens as number;
          output += usage.output_tokens as number;
          found = true;
        }
        continue;
      }

      // Legacy flat shape.
      const usage = parsed.usage as Record<string, unknown> | undefined;
      if (
        typeof usage?.input_tokens === "number" &&
        typeof usage?.output_tokens === "number"
      ) {
        input += usage.input_tokens as number;
        output += usage.output_tokens as number;
        found = true;
      }
    } catch {
      // Not a JSON line — skip.
    }
  }

  return found ? { input, output } : undefined;
}

